sys_ws_operation.operation_script:
(function process( /*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    // implement resource here
    var sysId = request.pathParams.sys_id;

    // Initialize response object
    var responseBody = {};

    if (sysId) {
        var gr = new GlideRecord('incident');
        if (gr.get(sysId)) {
            // Populate response with incident data
            responseBody.number = gr.getValue('number');
            responseBody.short_description = gr.getValue('short_description');
            responseBody.state = gr.getDisplayValue('state'); // Get display value for state
            response.setStatus(200); // OK
        } else {
            responseBody.error = "Incident not found with sys_id: " + sysId;
            response.setStatus(404); // Not Found
        }
    } else {
        responseBody.error = "sys_id parameter is missing.";
        response.setStatus(400); // Bad Request
    }

    response.setBody(responseBody);

})(request, response);
